<div className="lg-list">{shown.map((p:any)=><button className={'lg-card '+(p.result==='W'?'w':p.result==='L'?'l':'')} key={p.id} onClick={()=>onPick(p)}><LineupPortrait name={p.analyst}/><div className="lg-main"><b><R t={p.pick} s={p.sport}/> <em>{odds(p.odds)}</em>{p.lock&&<span className="lg-badge" title="Lock"><LockKeyhole size={15}/></span>}{p.analyst==='Johnny Biz'&&<span className="lg-badge" title="Boss ticket"><DenCrown size={15}/></span>}{isDen(p)&&<img className="lg-badge lg-lion" src="art/den-lion.webp" alt="Lions Den game" title="Lions Den game"/>}{p.research&&<span className="lg-badge" title={'Research: '+p.research.verdict+(p.research.note?' — '+p.research.note:'')}>{verdictIcon[p.research.verdict]||''}</span>}</b><small><R t={p.matchup} s={p.sport}/></small><small>{short(p.analyst)} · {p.sport} · {p.market==='ML'?'Moneyline':p.market} · {new Date(p.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small></div><div className="lg-form" title={p.form?'Last '+p.form.n+' settled '+p.sport+' '+(p.market==='ML'?'moneylines':p.market.toLowerCase()+'s'):''}>{p.form&&p.form.n?<><strong className={p.form.rate===null?'':p.form.rate>=0.55?'green':p.form.rate<0.5?'red':''}>{p.form.rate===null?'—':Math.round(p.form.rate*100)+'%'}</strong><small>{p.form.w}–{p.form.l}{p.form.push?'–'+p.form.push:''}</small><em>L{p.form.n}</em></>:<small>no history</small>}</div><div className="lg-res"><span className={'lg-mark '+(p.result==='W'?'w':p.result==='L'?'l':'p')}>{p.result==='W'?'✓':p.result==='L'?'✕':p.result==='Push'?'∞':'•'}</span><small className={(p.net||0)>0?'green':(p.net||0)<0?'red':''}>{p.result?signed(p.net):'pending'}</small></div></button>)}</div>
{!shown.length&&!waiting&&<Empty text="Nothing in the book for these filters."/>}{waiting&&!shown.length&&<p className="lg-loading">Opening the book…</p>}
{v.count>50&&<div className="pagination"><button disabled={!page} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page+1} of {Math.ceil(v.count/50)}</span><button disabled={(page+1)*50>=v.count} onClick={()=>setPage(page+1)}>Next</button></div>}
