function PickEditor({pick:p,save,busy}:{pick:any,save:(b:any)=>Promise<boolean>,busy:boolean}){const [action,setAction]=useState('correct'),[selection,setSelection]=useState(p.pick),[price,setPrice]=useState(String(p.odds||'')),[result,setResult]=useState('W'),[rank,setRank]=useState('1'),[reason,setReason]=useState('');return <><div className="eyebrow">{p.date} · {p.sport} · {p.market}</div><h2><R t={p.pick} s={p.sport}/></h2><p><R t={p.matchup} s={p.sport}/></p><div className="submission"><span><Avatar name={p.analyst}/>{p.analyst}</span><b>{odds(p.odds)} · {money(p.risk)} risk</b></div><p className="muted">{p.source}</p><div className="filters"><label>Action<select value={action} onChange={e=>setAction(e.target.value)}><option value="correct">Correct pending pick</option><option value="set_quote">Apply verified shared quote to crew</option><option value="settle">Settle verified result</option><option value="lock">Freeze as a lock</option></select></label></div><form onSubmit={e=>{e.preventDefault();save({action,id:p.id,expectedRevision:p.openedRevision,pick:selection,odds:Number(price),result,rank:Number(rank),reason})}}>{(action==='correct'||action==='set_quote')&&<div className="form-row"><label>Selection<input value={selection} onChange={e=>setSelection(e.target.value)} required/></label><label>American odds<input type="number" value={price} onChange={e=>setPrice(e.target.value)} required/></label></div>}{action==='settle'&&<label>Verified outcome<select value={result} onChange={e=>setResult(e.target.value)}>{['W','L','Push','Void'].map(s=><option key={s}>{s}</option>)}</select></label>}{action==='lock'&&<label>Available rank (1–5)<select value={rank} onChange={e=>setRank(e.target.value)}>{Array.from({length:12},(_,i)=>i+1).map(n=><option key={n}>{n}</option>)}</select></label>}<label>Source / reason<textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="Verified source or reason for this change" required/></label><button className="primary" disabled={busy}>{busy?'Saving…':'Save with audit record'}</button></form><p className="muted">Every change creates a revision. Frozen locks keep their original selection and pregame grade.</p></>}
class Catch extends Component<{children:any},{err:string}>{state={err:''};static getDerivedStateFromError(e:any){return {err:String(e?.message||e)}}render(){return this.state.err?<div className="panel" style={{padding:20}}><h2>Page tripped</h2><p>Screenshot this for Hova: {this.state.err}</p></div>:this.props.children}}
const ymd=(d:Date)=>d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0');
const toUTC=(d:string)=>{const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(String(d||''));return m?new Date(Date.UTC(+m[1],+m[2]-1,+m[3],12)):null};
const addDays=(d:string,n:number)=>{const t=toUTC(d);return t?ymd(new Date(t.getTime()+n*86400000)):d};
function weekMonday(d:string){const t=toUTC(d);if(!t)return '';return addDays(d,-((t.getUTCDay()+6)%7))}
function centralToday(){try{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));if(p.year&&p.month&&p.day)return p.year+'-'+p.month+'-'+p.day}catch{}return ymd(new Date(Date.now()-6*3600000))}
const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'],MON=MONTHS.map(m=>m.slice(0,3));
const shortDay=(d:string)=>{const t=toUTC(d);return t?MON[t.getUTCMonth()]+' '+t.getUTCDate():d};
const signed=(c:number)=>(c>0?'+':c<0?'−':'')+money(Math.abs(c));
function Cash({data}:{data:any}){const wk=weekMonday(centralToday()),snapD=String(data.cash.date||''),since=snapD>wk?snapD:wk,weekTix=((data.myWagers||[]) as any[]).filter(r=>r.date>=wk&&(snapD<=wk||r.date>snapD)&&r.net!==null&&r.net!==undefined),bookieNow=(snapD>=wk?(data.cash.bookie||0):0)+weekTix.reduce((t:number,r:any)=>t+(r.net||0),0),lastTix=weekTix.reduce((m:string,r:any)=>r.date>m?r.date:m,''),bookieAsOf=lastTix>since?lastTix:since;const rows=((data.myWagers||[]) as any[]).filter(r=>toUTC(r.date));const now=centralToday();const months=useMemo(()=>[...new Set([weekMonday(now).slice(0,7)||now.slice(0,7),...rows.map(r=>weekMonday(r.date).slice(0,7))])].sort().reverse(),[rows.length]);const years=[...new Set(months.map(m=>m.slice(0,4)))];const [month,setMonth]=useState(months[0]);const yearMode=month.startsWith('Y');const yr=yearMode?month.slice(1):'';const mondays:string[]=[];if(!yearMode)for(let d=1;d<=31;d++){const s=month+'-'+String(d).padStart(2,'0');const dt=toUTC(s);if(!dt||ymd(dt)!==s)break;if(dt.getUTCDay()===1)mondays.push(s)}const curQ=now.slice(0,4)+'-Q'+Math.ceil(+now.slice(5,7)/3);const weeks=yearMode?[1,2,3,4].map(q=>{const ms=[0,1,2].map(k=>yr+'-'+String((q-1)*3+k+1).padStart(2,'0'));const key=yr+'-Q'+q;return {n:q,q:true,name:['1ST','2ND','3RD','4TH'][q-1]+' QUARTER',dates:MON[(q-1)*3]+' – '+MON[(q-1)*3+2],live:key===curQ,future:key>curQ,...summarize(rows.filter(r=>ms.includes(weekMonday(r.date).slice(0,7))))}}):mondays.map((mon,i)=>{const sun=addDays(mon,6);return {n:i+1,name:'WEEK '+(i+1),dates:shortDay(mon)+' – '+shortDay(sun),live:mon<=now&&now<=sun,future:mon>now,...summarize(rows.filter(r=>r.date>=mon&&r.date<=sun))}});const tot=summarize(rows.filter(r=>yearMode?weekMonday(r.date).slice(0,4)===yr:weekMonday(r.date).slice(0,7)===month));const label=(m:string)=>(MONTHS[+m.slice(5,7)-1]||m)+' '+m.slice(0,4);const rec=(s:any)=>s.w+'-'+s.l+(s.push?'-'+s.push:'');return <><h2 className="br-section">This week with the Bookie</h2><div className="stats-row br-stats"><Stat label="MONEY IN THE STASH" value={money(data.cash.cash)}/><Stat label={bookieNow>100?'PLAY MONEY':'LOST MONEY'} value={money(Math.abs(bookieNow))} sub="Resets every Monday"/><Stat label="ACTUAL BANKROLL" value={money(data.cash.cash+bookieNow)} sub="Stash minus the bookie"/><Stat label="BALANCE UPDATED" value={bookieAsOf}/></div><div className="br-head"><select className="br-month" value={month} onChange={e=>setMonth(e.target.value)} aria-label="Choose month or year">{years.map(y=><option key={'Y'+y} value={'Y'+y}>{y} Annual</option>)}{months.map(m=><option key={m} value={m}>{label(m)}</option>)}</select><div className="br-total"><span>{yearMode?'ANNUAL':'MONTH'} · {tot.net>0?'CASHED OUT':tot.net<0?'FUCKED OFF':'EVEN'}</span><strong className={tot.net>0?'green':tot.net<0?'red':''}>{signed(tot.net)}</strong><small>{rec(tot)}{tot.pending?' · '+tot.pending+' pending':''}</small></div></div><div className="br-weeks">{weeks.map((w:any)=>{const future=w.future,live=w.live,played=w.count>0;return <div key={w.n} className={'br-week'+(live?' live':'')+(future||!played?' quiet':'')}><div className="br-week-name"><b>{w.name}</b><small>{w.dates}</small>{live&&<em>{w.q?'THIS QUARTER':'THIS WEEK'}</em>}</div><div className="br-week-rec">{played?rec(w):future?'Not here yet':'No bets'}{w.pending?<small>{w.pending} pending</small>:null}</div><strong className={'br-week-net '+(w.net>0?'green':w.net<0?'red':'')}>{played?signed(w.net):'—'}<small>{played?(w.net>0?'CASHED OUT':w.net<0?'FUCKED OFF':'EVEN'):''}</small></strong></div>})}</div></>}
function ImportForm({data,save,busy}:{data:any,save:(b:any)=>Promise<boolean>,busy:boolean}){const [analyst,setAnalyst]=useState("G' Money"),[date,setDate]=useState(data.date),[source,setSource]=useState(''),[text,setText]=useState(''),[preview,setPreview]=useState<any[]|null>(null),[error,setError]=useState('');function parse(){try{let picks:any[];if(text.trim().startsWith('['))picks=JSON.parse(text);else{picks=[];for(const line of text.split('\n').filter(s=>s.trim())){const cells=line.split('|').map(s=>s.trim());if(cells.length!==5)throw Error('Use SPORT | MATCHUP | SPREAD: pick (odds) | TOTAL: pick (odds) | ML: pick (odds)');const [sport,matchup,...markets]=cells;markets.forEach((cell,i)=>{if(!cell||cell==='—'||/^(pass|skip)$/i.test(cell))return;let clean=cell.replace(/^(SPREAD|TOTAL|ML):\s*/i,'');const m=clean.match(/^(.*?)\s*\(([+−-]?\d+)\)\s*$/);if(!m)throw Error('Missing odds in: '+cell);let pick=m[1].replace(/^U\s+(\d)/i,'Under $1').replace(/^O\s+(\d)/i,'Over $1');if(i===2&&!/\bML\b/i.test(pick))pick+=' ML';picks.push({date,analyst,sport,matchup,pick,odds:Number(m[2].replace('−','-')),market:['Spread','Total','ML'][i],risk:20000,grade:''})})}}if(!picks.length)throw Error('No picks found');setPreview(picks);setError('')}catch(e){setError(String(e));setPreview(null)}}return <div className="panel form-panel import-panel"><h2>Verified picks. One clean import.</h2><p>Use the same verified DraftKings lines for every analyst’s new card. Include the quote timestamp in provenance. Paste the full-game card in your usual format, or a JSON array with exact stakes in cents for Johnny Biz.</p><div className="form-row"><label>Analyst<select value={analyst} onChange={e=>{setAnalyst(e.target.value);setPreview(null)}}>{[...crew,'Johnny Biz'].map(a=><option key={a}>{a}</option>)}</select></label><label>Central date<input type="date" value={date} onChange={e=>{setDate(e.target.value);setPreview(null)}}/></label></div><label>Source / provenance<input value={source} onChange={e=>setSource(e.target.value)} placeholder="e.g. G’s supplied card, verified DraftKings prices and timestamp" required/></label><label>Pick card<textarea className="import-input" value={text} onChange={e=>{setText(e.target.value);setPreview(null)}} placeholder={'NFL | Browns at Saints | SPREAD: Saints -3 (-125) | TOTAL: U 42.5 (-110) | ML: Saints (-175)'}/></label><div className="button-row"><button className="primary" onClick={parse}>Review import</button><a href="/api/export">Download JSON format <Download size={14}/></a></div>{error&&<div className="alert error">{error}</div>}{preview&&<><div className="section-title"><h3>{preview.length} picks ready for validation</h3><span>Duplicates are skipped</span></div><div className="table-wrap"><table><thead><tr>{['Sport','Analyst','Matchup','Market','Pick','Odds','Risk'].map(s=><th key={s}>{s}</th>)}</tr></thead><tbody>{preview.map((p,i)=><tr key={i}><td>{p.sport}</td><td>{p.analyst}</td><td><R t={p.matchup} s={p.sport}/></td><td>{p.market}</td><td><R t={p.pick} s={p.sport}/></td><td>{p.odds}</td><td>{money(p.risk)}</td></tr>)}</tbody></table></div><button className="primary" disabled={busy||!source.trim()||analyst==='Johnny Biz'&&!text.trim().startsWith('[')} onClick={async()=>{if(await save({action:'import',picks:preview,source})){setPreview(null);setText('')}}}>Commit verified picks</button>{analyst==='Johnny Biz'&&<p>Use JSON with your exact ticket stakes; the crew card defaults to $200 risk.</p>}</>}</div>}
/* Boss 11/19 Data Health rebuild: plain-English checklist, green/red lights, no fine print. */
function Health({data}:{data:any}){const [ln,setLn]=useState<any>(null);const tick=useTick();useEffect(()=>{fetch('/api/ledger?range=lastnight').then(r=>r.json()).then(setLn).catch(()=>setLn({error:true}))},[data.revision,tick]);
const today=(data.current||[]).filter((p:any)=>p.date===data.date);const locksToday=(data.locks||[]).filter((l:any)=>(l.date||l.slate_date)===data.date);const names=[...crew,'Johnny Biz'];
const count=(n:string)=>today.filter((p:any)=>p.analyst===n).length,lockN=(n:string)=>locksToday.filter((l:any)=>l.analyst===n).length;
const Check=({ok,warn,title,detail}:{ok:boolean,warn?:boolean,title:string,detail:any})=><div className={'hc '+(ok?'ok':warn?'warn':'bad')}><span className="hc-dot"/><div><b>{title}</b><small>{detail}</small></div></div>;
const pend=ln?.summary?.pending;const rithmm=count('Rithmm');const missingCards=crew.filter(n=>!count(n));const shortLocks=crew.filter(n=>count(n)&&lockN(n)<12);
const dl=async(path:string,name:string,type:string)=>{const t=await (await fetch(path)).text();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type}));a.download=name;a.click()};
return <><div className="hc-list">
<Check ok={!missingCards.length} title={missingCards.length?'Missing cards tonight: '+missingCards.map(short).join(', '):'Every analyst has a card tonight'} detail={crew.map(n=>short(n)+' '+count(n)).join(' · ')}/>
<Check ok={!shortLocks.length&&!missingCards.length} warn={!!shortLocks.length} title={shortLocks.length?'Short on locks: '+shortLocks.map(n=>short(n)+' ('+lockN(n)+')').join(', '):'Everybody has 12 locks'} detail={crew.map(n=>short(n)+' '+lockN(n)).join(' · ')}/>
<Check ok={rithmm>12} warn={rithmm>0&&rithmm<=12} title={rithmm>12?'Rithmm full card logged ('+rithmm+')':rithmm?'Rithmm only has his '+rithmm+' top plays — Caution Plays not logged yet':'Rithmm not logged yet'} detail="Top Predictions + Caution Plays with a positive edge"/>
<Check ok={pend===0} warn={pend>0} title={ln==null?'Checking last night…':pend===0?'Last night is fully graded':pend+' picks from last night still not graded'} detail={ln?.summary?ln.summary.w+'–'+ln.summary.l+' · '+signed(ln.summary.net):''}/>
<Check ok={data.denDate===data.date} warn title={data.denDate===data.date?'Lions Den is built for tonight':'Lions Den not built for tonight yet'} detail={data.denDate?'Last built for '+data.denDate:'Never built'}/>
<Check ok={!!count('Johnny Biz')} warn title={count('Johnny Biz')?'Your tickets are logged ('+count('Johnny Biz')+')':'None of your tickets logged tonight'} detail="Send the slip screenshot and Hova logs it"/>
<Check ok title={'The book: '+Number(data.count||0).toLocaleString()+' picks'} detail={'Last pick date '+(data.sourceDate||'—')}/>
</div>
<div className="hc-export"><button className="primary link-button" onClick={()=>dl('/api/export','la-cosa-nostra-book.csv','text/csv')}><Download size={16}/> Download the whole book (spreadsheet)</button><button className="link-button hc-alt" onClick={()=>dl('/api/backup','la-cosa-nostra-backup.json','application/json')}><Download size={16}/> Full backup (picks, locks, settings)</button></div></>}

function LockEditor({lock,save,busy}:{lock:any,save:(b:any)=>Promise<boolean>,busy:boolean}){const original=lockTerms(lock);const [result,setResult]=useState('W'),[risk,setRisk]=useState(original.risk?String(original.risk/100):''),[price,setPrice]=useState(original.odds?String(original.odds):''),[reason,setReason]=useState(''),[done,setDone]=useState(false);return <><div className="eyebrow">FROZEN LOCK · {lock.date}</div><h2>{short(lock.analyst)} · #{lock.rank}</h2><p style={{whiteSpace:'pre-line'}}>{lock.card}</p><p className="muted">Settle the original frozen selection. A later ledger correction does not change this card.</p>{done?<div className="alert success">Lock result saved.</div>:<form onSubmit={async e=>{e.preventDefault();if(await save({action:'settle_lock',id:lock.id,expectedRevision:lock.openedRevision,result,risk:Math.round(Number(risk)*100),odds:Number(price),reason}))setDone(true)}}><label>Verified outcome<select value={result} onChange={e=>setResult(e.target.value)}>{['W','L','Push','Void'].map(s=><option key={s}>{s}</option>)}</select></label><div className="form-row"><label>Original stake ($)<input type="number" step="0.01" required value={risk} disabled={original.risk!=null} onChange={e=>setRisk(e.target.value)}/></label><label>Original American odds<input type="number" required value={price} disabled={original.odds!=null} onChange={e=>setPrice(e.target.value)}/></label></div><label>Verified result source<textarea required value={reason} onChange={e=>setReason(e.target.value)}/></label><button disabled={busy} className="primary">Settle frozen lock</button></form>}</>}

function Cohorts({data,sport}:{data:any,sport:string}){const [size,setSize]=useState(2),[open,setOpen]=useState(''),[last,setLast]=useState<any>(null);const MINGAMES=20,roi=(p:any)=>p.risk?p.net/p.risk:-Infinity;const cohorts=(data.cohorts||data.pairs).filter((p:any)=>(sport==='All'||p.sport===sport)&&p.names.length===size&&p.w+p.l>=MINGAMES&&p.risk>0).sort((a:any,b:any)=>roi(b)-roi(a)||b.net-a.net);const shown=cohorts.slice(0,5);/* Boss 11/19: top 5 only; tap the pictures for tonight's games they agree on */const side=(x:any)=>String(x.pick||'').toLowerCase().replace(/[^a-z]/g,'');const tonight=(c:any)=>{const by:any={};for(const x of (data.current||[]))if(c.names.includes(x.analyst)&&x.sport===c.sport&&x.market===c.market){const k=x.matchup+'|'+side(x);(by[k]??={}).picks??=[];by[k].picks.push(x)}return Object.values(by).filter((g:any)=>c.names.every((n:string)=>g.picks.some((x:any)=>x.analyst===n))).map((g:any)=>g.picks[0])};return <><div className="section-title"><h2>Partners in Crime</h2><select aria-label="Agreement group size" value={size} onChange={e=>{setSize(Number(e.target.value));setOpen('')}}><option value={2}>Duos</option><option value={3}>Triples</option><option value={4}>Quads</option></select></div><div className="crime-list">{shown.map((p:any,i:number)=>{const key=p.names.join()+p.sport+p.market;const isOpen=open===key;const games=isOpen?tonight(p):[];return <div className={'crime-wrap'+(isOpen?' open':'')} key={key}><div className="crime-row crime-click" role="button" tabIndex={0} onClick={()=>{setOpen(isOpen?'':key);setLast(null)}}><span className="crime-rank">{i+1}</span><span className="card-avatars crime-faces">{p.names.map((n:string)=><LineupPortrait name={n} key={n}/>)}</span><div className="crime-who"><b>{p.names.map(short).join(' + ')}</b><small>{p.sport} · {p.market==='ML'?'Moneyline':p.market} · {p.w}–{p.l}{p.push?'–'+p.push:''} · {pct(p.w/(p.w+p.l))}</small></div><div className="crime-money"><strong className={p.net>0?'green':p.net<0?'red':''}>{((p.net/p.risk)*100>0?'+':'')+((p.net/p.risk)*100).toFixed(1)+'%'}<em className="crime-roi">ROI</em></strong><small>{signed(p.net)}</small></div></div>{isOpen&&<div className="crime-tonight"><div className="crime-tonight-head">Tonight together · {games.length} {games.length===1?'game':'games'}{games.length?' · '+games.filter((g:any)=>g.result==='W').length+'–'+games.filter((g:any)=>g.result==='L').length:''}</div>{games.map((g:any)=><div className="crime-game" key={g.id}><span className={'crime-mark '+(g.result==='W'?'w':g.result==='L'?'l':'p')}>{g.result==='W'?'✓':g.result==='L'?'✕':g.result==='Push'?'∞':'•'}</span><div><b><R t={g.pick} s={g.sport}/> <em>{odds(g.odds)}</em></b><small><R t={g.matchup} s={g.sport}/></small></div></div>)}{!games.length&&<small className="crime-none">Not on the same side of anything tonight.</small>}<button className="crime-last-btn" onClick={async e=>{e.stopPropagation();if(last){setLast(null);return}setLast('loading');const r=await fetch('/api/together?'+new URLSearchParams({names:p.names.join('|'),sport:p.sport,market:p.market}));setLast(await r.json())}}>{last?'Hide last 10 games':'Last 10 games'}</button>{last&&<div className="crime-last">{last==='loading'?<small className="crime-none">Pulling the tape…</small>:<><div className="crime-tonight-head">Last {last.length} together · {last.filter((g:any)=>g.result==='W').length}–{last.filter((g:any)=>g.result==='L').length}{last.some((g:any)=>g.result==='Push')?'–'+last.filter((g:any)=>g.result==='Push').length:''}</div>{last.map((g:any)=><div className="crime-game" key={g.id}><span className={'crime-mark '+(g.result==='W'?'w':g.result==='L'?'l':'p')}>{g.result==='W'?'✓':g.result==='L'?'✕':'∞'}</span><div><b><R t={g.pick} s={g.sport}/> <em>{odds(g.odds)}</em></b><small>{new Date(g.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} · <R t={g.matchup} s={g.sport}/></small></div></div>)}{!last.length&&<small className="crime-none">No graded games together yet.</small>}</>}</div>}</div>}</div>})}</div>{!cohorts.length&&<Empty text="Nobody has 20+ games together at this size yet."/>}</>}

function VerifiedGradeImport({data,save,busy}:{data:any;save:(b:any)=>Promise<boolean>;busy:boolean}){const [text,setText]=useState(''),[plan,setPlan]=useState<any[]|null>(null),[revision,setRevision]=useState(0),[error,setError]=useState(''),[done,setDone]=useState('');return <details className="panel form-panel"><summary>Import verified final grades</summary><p>Review a source-backed grading batch before committing. Original lines, prices, stakes and cash balances are preserved.</p><label>Verified grade batch<textarea aria-label="Verified grade batch" value={text} onChange={e=>{setText(e.target.value);setPlan(null);setDone('')}}/></label><button className="primary" onClick={()=>{try{const rows=JSON.parse(text);if(!Array.isArray(rows)||!rows.length||rows.length>600||rows.some(r=>!r.id||!['W','L','Push','Void'].includes(r.result)||!r.reason))throw Error('Provide 1–600 source-backed grades.');if(new Set(rows.map(r=>r.id)).size!==rows.length)throw Error('Duplicate record IDs');setPlan(rows);setRevision(data.revision);setError('')}catch(e){setError(String(e))}}}>Review final grades</button>{plan&&<><p>{plan.length} verified grades · {plan.filter(p=>p.result==='W').length} wins · {plan.filter(p=>p.result==='L').length} losses · {plan.filter(p=>p.result==='Push').length} pushes</p><div className="table-wrap"><table><thead><tr><th>Record</th><th>Result</th><th>Verified source</th></tr></thead><tbody>{plan.map(p=><tr key={p.id}><td>{p.id}</td><td>{p.result}</td><td>{p.reason}</td></tr>)}</tbody></table></div><button className="primary" disabled={busy} onClick={async()=>{if(await save({action:'settle_batch',grades:plan,reason:'Owner-authorized verified final-score grading batch',expectedRevision:revision,requestId:'grade-batch-'+crypto.randomUUID()})){setPlan(null);setText('');setDone('Verified final grades saved.')}}}>Commit verified final grades</button></>}{error&&<p role="alert">{error}</p>}{done&&<p role="status">{done}</p>}</details>}

function AnalystLockStats({data,name}:{data:any,name:string}){const rows=data.lockHistory.filter((l:any)=>l.analyst===name&&l.date<=data.date);const [sport,setSport]=useState('All');const sports=['All','NBA','NFL','CBB','CFB',...new Set<string>(rows.map((l:any)=>l.sport).filter((s:string)=>s&&!['NBA','NFL','CBB','CFB'].includes(s)))];const filtered=rows.filter((l:any)=>sport==='All'||l.sport===sport);const all=summarize(filtered);const grades=['A+','A','A-','B+','B','B-','C+','C','C-','Ungraded'];return <><div className="analyst-lock-heading"><img src={'art/jail-'+art[name]+(name==='Nino Brown'?'-diesel':'')+'.webp'} alt={name+' jailhouse portrait'}/><div><span className="eyebrow">LOCKS RECORD · ALL SAVED HISTORY</span><h2>{short(name)}</h2></div></div><div className="lock-stat-sports" role="group" aria-label="Locks record sport">{sports.map(s=><button key={s} className={sport===s?'selected':''} aria-pressed={sport===s} onClick={()=>setSport(s)}>{s==='All'?'All Sports':s}</button>)}</div><div className="stats-row"><Stat label="LOCKS RECORD" value={all.w+'–'+all.l} sub={all.push+' pushes · '+all.pending+' pending'}/><Stat label="WINNING %" value={pct(all.rate)}/><Stat label="ROI" value={pct(all.roi)} positive={all.roi===null?undefined:all.roi>=0}/><Stat label="RECORDED NET" value={money(all.net)} positive={all.net>=0}/></div>{(()=>{const last=filtered.filter((l:any)=>['W','L','Push'].includes(l.result)).sort((a:any,b:any)=>b.date.localeCompare(a.date)||(a.rank||0)-(b.rank||0)).slice(0,7);const md=(d:string)=>{const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(d);return m?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][+m[2]-1]+' '+(+m[3]):d};return <><h3>Last {last.length} locks · {sport==='All'?'all sports':sport}</h3><div className="recent-agree">{last.length?last.map((l:any,i:number)=>{const lines=String(l.card||'').split('\n');return <div className="recent-row" key={i}><span className={'recent-mark '+(l.result==='W'?'green':l.result==='L'?'red':'')}>{l.result==='W'?'✓':l.result==='L'?'✕':'∞'}</span><div><b>{(lines[0]||'').replace(/^[ABC][+−-]?\s*\|\s*/i,'').replace(/^\d+\s*[•.)]?\s*/,'')}</b><small>{[lines[1]&&!/^GRADE/i.test(lines[1])?lines[1].replace(/\s*•\s*/,' · '):l.sport,md(l.date)].filter(Boolean).join(' · ')}</small></div></div>}):<p className="muted">No settled locks yet.</p>}</div></>})()}<h3>{sport==='All'?'All sports':' '+sport} · by grade</h3><div className="table-wrap lock-grade-table"><table><thead><tr><th>GRADE</th><th>W–L</th><th>PUSH</th><th>PENDING</th><th>WIN %</th><th>ROI</th></tr></thead><tbody>{grades.map(g=>{const r=summarize(filtered.filter((l:any)=>g==='Ungraded'?!/^[ABC]/.test(l.grade||''):l.grade===g));return <tr key={g}><td>{g}</td><td>{r.w}–{r.l}</td><td>{r.push}</td><td>{r.pending}</td><td>{pct(r.rate)}</td><td>{pct(r.roi)}</td></tr>})}</tbody></table></div></>}

function LoserDuo({duo,onClick}:{duo:any,onClick:()=>void}){return <section className="loser-duo panel" aria-label="Worst winning duo"><span className="eyebrow">THE FADE FILE · LAST 14 DAYS</span><h2>a bunch of fucking losers</h2>{duo?<><button className="loser-duo-button" aria-label="View duo two-week record" onClick={onClick}><img className="loser-duo-photo" src={'art/losers/'+duo.names.map((name:string)=>art[name]).sort().join('-')+'.webp'} alt={duo.names.map(short).join(' and ')+' raggedy duo portrait'}/></button><small className="muted">Tap photo for their record by sport</small><h3>{duo.names.map(short).join(' + ')}</h3><div className="loser-duo-stats"><div><span>MONEY TOGETHER</span><strong className={duo.net>0?'green':'red'}>{suspectMoney(duo.net)}</strong></div><div><span>SHARED RECORD</span><strong>{duo.w}–{duo.l}</strong><small>{duo.push} pushes</small></div><div><span>WINNING % TOGETHER</span><strong>{suspectPct(duo.rate)}</strong><small>{duo.w+duo.l} decisions</small></div></div></>:<p>No losers this week. Somebody check the math.</p>}</section>}

function LoserStats({duo}:{duo:any}){if(!duo)return <Empty text="No qualifying duo yet."/>;const rows=['NBA','NFL','CBB','CFB'].map(sport=>duo.bySport?.find((r:any)=>r.sport===sport)||{sport,w:0,l:0,push:0});return <><span className="eyebrow">SHARED PICKS · LAST 14 DAYS</span><h2>{duo.names.map(short).join(' + ')}</h2><p>{duo.from} through {duo.through}</p><div className="stats-row"><Stat label="SHARED RECORD" value={duo.w+'–'+duo.l} sub={duo.push+' pushes'}/><Stat label="WINNING %" value={suspectPct(duo.rate)}/></div><div className="table-wrap"><table className="suspect-sport-table"><thead><tr><th>SPORT</th><th>W–L</th><th>PUSH</th><th>WIN %</th></tr></thead><tbody>{rows.map(r=><tr key={r.sport}><th>{r.sport}</th><td>{r.w}–{r.l}</td><td>{r.push}</td><td>{suspectPct(r.w+r.l?r.w/(r.w+r.l):null)}</td></tr>)}</tbody></table></div><p className="muted">Matching settled picks at the same saved side, line and price. Each shared pick counted once. Pushes excluded from winning percentage.</p></>}

function LineupPortrait({name,vault=false}:{name:string,vault?:boolean}){return art[name]&&vault?<img className="lineup-portrait vault-portrait" src={'art/vault-'+art[name]+'.webp'} alt={name+' at the vault'}/>:art[name]?<img className="lineup-portrait" src={'art/jail-'+art[name]+(name==='Nino Brown'?'-diesel':'')+'.webp'} alt={name+' lineup portrait'}/>:<Avatar name={name} size={48}/>}

function DenOutcome({result}:{result:string}){return <div className={'den-outcome '+(result==='W'?'green':result==='L'?'red':'')} aria-label={'Spread result: '+(result==='W'?'Won':result==='L'?'Lost':result)}><strong>{result==='W'?'✓':result==='L'?'✕':result==='Push'?'—':'·'}</strong><span>{result==='W'?'Covered':result==='L'?'Did not cover':result==='Push'?'Push':result==='Unavailable'?'Result unavailable':result}</span></div>}
